(2499,'2019-09-29 20:42:40','2019-09-29 20:42:40','Minmatar Mining Station','',0,30592,1,0,0,15,0,1,1,1135),
(2500,'2019-09-29 20:42:44','2019-09-29 20:42:44','Minmatar Research Station','',0,33481,1,0,0,15,0,1,1,1136),
